+export function increment() {
+  // Serialize increments through an async queue so the read-modify-write
+  // never interleaves between concurrent callers.
+  return new Promise((resolve, reject) => {
+    queue.push({ resolve, reject });
+    if (!running) {
+      running = true;
+      // Defer draining so the callback is never invoked synchronously.
+      setImmediate(drain);
+    }
+  });
+}
+
+async function drain() {
+  while (queue.length > 0) {
+    const { resolve, reject } = queue.shift();
+    try {
+      // Simulated async work happens inside the critical section.
+      await new Promise((r) => setTimeout(r, 1));
+      value += 1;
+      resolve();
+    } catch (err) {
+      reject(err);
+    }
+  }
